  ];

  badge = {
    ZIP:{bg:'#b3973f'},
    PAK:{bg:'#be7440'},
    STR:{bg:'#8a6cae'},
    EXE:{bg:'#4d8f9e'},
  };

  pcs = ['TONYA-PC','S-PC793','MY-PC','S-NB264'];

  state = {
    a:{q:'',type:'ALL',sortKey:'date',sortDir:'desc',sel:'r1',removed:[],pinned:['r1']},
    b:{q:'',type:'ALL',sel:'r1',removed:[],open:{'TONYA-PC':true,'S-PC793':true,'MY-PC':true,'S-NB264':true}},
    c:{q:'',type:'ALL',pc:'ALL',sortKey:'name',sortDir:'asc',sel:'r4',view:'list',removed:[]},
  };

  acc(){ return (this.props.accent==='Оранжевый') ? '#c87a2a' : '#4772b3'; }

  upd(v,patch){ this.setState(s=>({[v]:Object.assign({},s[v],patch)})); }

  parseTs(s){ const a=s.split(' '); const d=a[0].split('.').map(Number); const t=a[1].split(':').map(Number); return new Date(d[2],d[1]-1,d[0],t[0],t[1]).getTime(); }

  base(vs){ return this.rawData.filter(r=>vs.removed.indexOf(r.id)===-1); }

  filt(rows,q,type){
    const Q=(q||'').trim().toLowerCase();
    return rows.filter(r=>{
      if(type && type!=='ALL' && r.type!==type) return false;
      if(Q && (r.name.toLowerCase().indexOf(Q)===-1 && r.pc.toLowerCase().indexOf(Q)===-1)) return false;
      return true;
    });
  }

  sortRows(rows,key,dir){
    const mul = dir==='asc'?1:-1;
    const arr=rows.slice();
    arr.sort((a,b)=>{
      if(key==='size') return mul*(a.bytes-b.bytes);
      if(key==='date') return mul*(this.parseTs(a.date)-this.parseTs(b.date));
      if(key==='pc') return mul*a.pc.localeCompare(b.pc);
      if(key==='type') return mul*a.type.localeCompare(b.type);
      return mul*a.name.localeCompare(b.name,'ru');
    });
    return arr;
  }

  toggleSort(v,key){
    const vs=this.state[v];
    if(vs.sortKey===key){ this.upd(v,{sortDir: vs.sortDir==='asc'?'desc':'asc'}); }
    else { this.upd(v,{sortKey:key, sortDir:'asc'}); }
  }

  del(v,id){ const vs=this.state[v]; this.upd(v,{removed:vs.removed.concat([id]), sel: vs.sel===id?null:vs.sel}); }
  togglePin(v,id){ const vs=this.state[v]; const has=vs.pinned.indexOf(id)!==-1; this.upd(v,{pinned: has? vs.pinned.filter(x=>x!==id):vs.pinned.concat([id])}); }
  clearAll(v){ this.upd(v,{removed:this.rawData.map(r=>r.id), sel:null}); }
  refresh(v){ this.upd(v,{removed:[]}); }
  copyStr(name){ try{ if(navigator.clipboard) navigator.clipboard.writeText(name); }catch(e){} }

  fmtCount(n){
    const a=Math.abs(n)%100, b=n%10; let w;
    if(a>10 && a<20) w='объектов'; else if(b===1) w='объект'; else if(b>=2 && b<=4) w='объекта'; else w='объектов';
    return n+' '+w;
  }

  icon(name){
    const E=React.createElement;
    const p={width:15,height:15,viewBox:'0 0 24 24',fill:'none',stroke:'currentColor',strokeWidth:2,strokeLinecap:'round',strokeLinejoin:'round'};
    const m={
      download:[E('path',{key:1,d:'M12 3v12'}),E('path',{key:2,d:'M7 11l5 5 5-5'}),E('path',{key:3,d:'M5 21h14'})],
      copy:[E('rect',{key:1,x:9,y:9,width:11,height:11,rx:2}),E('path',{key:2,d:'M5 15V5a2 2 0 0 1 2-2h10'})],
      trash:[E('path',{key:1,d:'M4 7h16'}),E('path',{key:2,d:'M9 7V4h6v3'}),E('path',{key:3,d:'M6 7l1 13h10l1-13'})],
      refresh:[E('path',{key:1,d:'M20 11a8 8 0 1 0-2 6'}),E('path',{key:2,d:'M20 4v6h-6'})],
      search:[E('circle',{key:1,cx:11,cy:11,r:7}),E('path',{key:2,d:'M21 21l-4-4'})],
      plus:[E('path',{key:1,d:'M12 5v14'}),E('path',{key:2,d:'M5 12h14'})],
      pin:[E('path',{key:1,d:'M9 3h6l-1 7 3 2v2H7v-2l3-2z'}),E('path',{key:2,d:'M12 16v5'})],
      link:[E('path',{key:1,d:'M9 15l6-6'}),E('path',{key:2,d:'M11 6l1-1a4 4 0 0 1 6 6l-1 1'}),E('path',{key:3,d:'M13 18l-1 1a4 4 0 0 1-6-6l1-1'})],
      file:[E('path',{key:1,d:'M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z'}),E('path',{key:2,d:'M14 3v5h5'})],
      grid:[E('rect',{key:1,x:4,y:4,width:7,height:7,rx:1}),E('rect',{key:2,x:13,y:4,width:7,height:7,rx:1}),E('rect',{key:3,x:4,y:13,width:7,height:7,rx:1}),E('rect',{key:4,x:13,y:13,width:7,height:7,rx:1})],
      list:[E('path',{key:1,d:'M8 6h12'}),E('path',{key:2,d:'M8 12h12'}),E('path',{key:3,d:'M8 18h12'}),E('path',{key:4,d:'M4 6h.01'}),E('path',{key:5,d:'M4 12h.01'}),E('path',{key:6,d:'M4 18h.01'})],
    };
    return E('svg',p,m[name]||null);
  }

  vrow(v,r,i,selId){
    const acc=this.acc();
    const sel = selId===r.id;
    const zebra = this.props.zebra && (i%2===1);
    const bd=this.badge[r.type]||{bg:'#777'};
    const isStr = r.type==='STR';
    const pinnedSet = this.state[v].pinned;
    const pinned = pinnedSet ? pinnedSet.indexOf(r.id)!==-1 : false;
    return {
      id:r.id, type:r.type, name:r.name, size:r.size, pc:r.pc, date:r.date,
      sel, isStr, badgeBg:bd.bg,
      bg: sel? acc : (zebra? 'rgba(255,255,255,0.022)':'transparent'),
      fg: sel? '#ffffff' : '#dadada',
      fgDim: sel? 'rgba(255,255,255,0.8)' : '#8a8a8a',
      pinned,
      pinColor: sel? (pinned?'#ffffff':'rgba(255,255,255,0.5)') : (pinned?acc:'#666666'),
      cardBg: sel? 'rgba(71,114,179,0.16)' : '#2f2f2f',
      cardBorder: sel? acc : '#171717',
      thumbBg: bd.bg+'2e',
      actionTitle: isStr?'Копировать строку':'Скачать',
      actionIcon: this.icon(isStr?'copy':'download'),
      iTrash: this.icon('trash'),
      iPin: this.icon('pin'),
      iLink: this.icon('link'),
      onSelect: ()=>this.upd(v,{sel:r.id}),
      onDelete: (e)=>{ e.stopPropagation(); this.del(v,r.id); },
      onPin: (e)=>{ e.stopPropagation(); this.togglePin(v,r.id); },
      onAction: (e)=>{ e.stopPropagation(); if(isStr) this.copyStr(r.name); },
    };
  }

  filterDefs(v,current){
    const acc=this.acc();
    const types=[['ALL','Все'],['ZIP','ZIP'],['STR','STR'],['PAK','PAK'],['EXE','EXE']];
    return types.map(t=>({key:t[0],label:t[1],active:current===t[0],
      bg: current===t[0]?acc:'transparent', fg: current===t[0]?'#fff':'#cdcdcd',
      on:()=>this.upd(v,{type:t[0]})}));
  }

  col(v,key){
    const vs=this.state[v];
    return {active:vs.sortKey===key, arrow:vs.sortDir==='asc'?'▲':'▼', on:()=>this.toggleSort(v,key)};
  }

  renderVals(){
    const acc=this.acc();
    const rowH = this.props.compact===false?34:29;

    // ---- A ----
    const va=this.state.a;
    const listA=this.sortRows(this.filt(this.base(va),va.q,va.type),va.sortKey,va.sortDir).map((r,i)=>this.vrow('a',r,i,va.sel));
    const selAobj=this.rawData.find(r=>r.id===va.sel && va.removed.indexOf(va.sel)===-1);

    // ---- B ----
    const vb=this.state.b;
    const fb=this.filt(this.base(vb),vb.q,vb.type);
    const groupsB=this.pcs.map(pc=>{
      const open=!!vb.open[pc];
      const items=fb.filter(r=>r.pc===pc);
      return {pc, open, chevron:open?'▾':'▸', count:items.length,
        items: open? items.map((r,i)=>this.vrow('b',r,i,vb.sel)) : [],
        onToggle:()=>this.upd('b',{open:Object.assign({},vb.open,{[pc]:!open})})};
    });
    const selBobj=this.rawData.find(r=>r.id===vb.sel && vb.removed.indexOf(vb.sel)===-1);
    let propRowsB=[], selBbadgeBg='#777', selBactionLabel='Скачать', selBactionIcon=this.icon('download');
    if(selBobj){
      const bd=this.badge[selBobj.type]||{bg:'#777'};
      selBbadgeBg=bd.bg;
      const str=selBobj.type==='STR';
      selBactionLabel=str?'Копировать':'Скачать';
      selBactionIcon=this.icon(str?'copy':'download');
      propRowsB=[
        {label:'Тип', value:selBobj.type},
        {label:'Имя', value:selBobj.name},
        {label:'Размер', value:selBobj.size},
        {label:'Компьютер', value:selBobj.pc},
        {label:'Добавлено', value:selBobj.date},
        {label:'Источник', value: str?'Текстовая строка':'Файл'},
      ];
    }

    // ---- C ----
    const vc=this.state.c;
    let rc=this.base(vc);
    if(vc.pc!=='ALL') rc=rc.filter(r=>r.pc===vc.pc);
    const listC=this.sortRows(this.filt(rc,vc.q,vc.type),vc.sortKey,vc.sortDir).map((r,i)=>this.vrow('c',r,i,vc.sel));
    const selCobj=this.rawData.find(r=>r.id===vc.sel && vc.removed.indexOf(vc.sel)===-1);
    const cBase=this.base(vc);
    const counts={}; cBase.forEach(r=>{counts[r.pc]=(counts[r.pc]||0)+1;});
    const pcListC=[{key:'ALL',label:'Все компьютеры',count:cBase.length}].concat(this.pcs.map(pc=>({key:pc,label:pc,count:counts[pc]||0}))).map(o=>({
      key:o.key,label:o.label,count:o.count,active:vc.pc===o.key,
      bg: vc.pc===o.key?acc:'transparent', fg: vc.pc===o.key?'#fff':'#cdcdcd',
      fgDim: vc.pc===o.key?'rgba(255,255,255,0.7)':'#7c7c7c',
      on:()=>this.upd('c',{pc:o.key})
    }));
    const sortKeysC=[['name','Имя'],['size','Размер'],['date','Дата']];
    const sortBtnsC=sortKeysC.map(k=>({key:k[0],label:k[1],active:vc.sortKey===k[0],
      arrow:vc.sortDir==='asc'?'▲':'▼',
      bg: vc.sortKey===k[0]?acc:'transparent', fg: vc.sortKey===k[0]?'#fff':'#cdcdcd',
      on:()=>this.toggleSort('c',k[0])}));
    const isList=vc.view==='list';
    const cStr=selCobj && selCobj.type==='STR';

    return {
      rowH,
      iRefresh:this.icon('refresh'), iTrashH:this.icon('trash'), iLinkH:this.icon('link'), iFileH:this.icon('file'),
      iSearchA:this.icon('search'), iSearchB:this.icon('search'), iSearchC:this.icon('search'),
      iList:this.icon('list'), iGrid:this.icon('grid'), iTrashB:this.icon('trash'), iTrashC:this.icon('trash'),

      // A
      listA, qA:va.q, onQA:e=>this.upd('a',{q:e.target.value}),
      filtersA:this.filterDefs('a',va.type),
      colTypeA:this.col('a','type'), colNameA:this.col('a','name'), colSizeA:this.col('a','size'), colPcA:this.col('a','pc'), colDateA:this.col('a','date'),
      noRowsA: listA.length===0,
      selNameA: selAobj?selAobj.name:'ничего не выбрано',
      countA:this.fmtCount(listA.length),
      refreshA:()=>this.refresh('a'), clearA:()=>this.clearAll('a'),

      // B
      qB:vb.q, onQB:e=>this.upd('b',{q:e.target.value}),
      filtersB:this.filterDefs('b',vb.type),
      groupsB,
      hasSelB:!!selBobj, noSelB:!selBobj, selB:selBobj||{type:'',name:''},
      selBbadgeBg, propRowsB, selBactionLabel, selBactionIcon,
      selBname: selBobj?selBobj.name:'—', countB:this.fmtCount(fb.length),
      copyB:()=>{ if(selBobj && selBobj.type==='STR') this.copyStr(selBobj.name); },
      delB:()=>{ if(selBobj) this.del('b',selBobj.id); },

      // C
      qC:vc.q, onQC:e=>this.upd('c',{q:e.target.value}),
      filtersC:this.filterDefs('c',vc.type),
      sortBtnsC, pcListC, listC,
      colNameC:this.col('c','name'), colSizeC:this.col('c','size'), colPcC:this.col('c','pc'), colDateC:this.col('c','date'),
      isListC:isList, isGridC:!isList,
      setListC:()=>this.upd('c',{view:'list'}), setGridC:()=>this.upd('c',{view:'grid'}),
      listBg:isList?acc:'transparent', listFg:isList?'#fff':'#cdcdcd',
      gridBg:!isList?acc:'transparent', gridFg:!isList?'#fff':'#cdcdcd',
      selCname: selCobj?selCobj.name:'—',
      selCactionLabel: cStr?'Копировать':'Скачать', selCactionIcon:this.icon(cStr?'copy':'download'),
      copyC:()=>{ if(cStr) this.copyStr(selCobj.name); },
      delC:()=>{ if(selCobj) this.del('c',selCobj.id); },
      viewLabelC: isList?'Вид: список':'Вид: сетка',
      countC:this.fmtCount(listC.length),
    };
  }
}

