upd(v,patch){ this.setState(s=>({[v]:Object.assign({},s[v],patch)})); }

componentDidMount(){
  this._onDoc=(e)=>{ if(this.state.a.open){ const el=this.comboRef.current; if(!el || !el.contains(e.target)) this.upd('a',{open:false}); } };
  document.addEventListener('mousedown', this._onDoc, true);
}
componentWillUnmount(){
  if(this._onDoc) document.removeEventListener('mousedown', this._onDoc, true);
  if(this._dlTimer){ clearInterval(this._dlTimer); this._dlTimer=null; }
}
catLabel(c){ return ({ALL:'Все',FILE:'Файл',STR:'Строка'})[c]||'Все'; }
filtA(rows,q,cat){
  const Q=(q||'').trim().toLowerCase();
  return rows.filter(r=>{
    if(cat==='FILE' && r.type==='STR') return false;
    if(cat==='STR' && r.type!=='STR') return false;
    if(Q && (r.name.toLowerCase().indexOf(Q)===-1 && r.pc.toLowerCase().indexOf(Q)===-1)) return false;
    return true;
  });
}
openDownload(r){
  if(this._dlTimer){ clearInterval(this._dlTimer); this._dlTimer=null; }
  this.setState({dl:{name:r.name, type:r.type, pc:r.pc, total:r.size, pct:0, status:'loading'}});
  this._dlTimer=setInterval(()=>{
    this.setState(s=>{
      if(!s.dl) return {};
      let p=s.dl.pct + 2 + Math.random()*4;
      if(p>=100){ if(this._dlTimer){ clearInterval(this._dlTimer); this._dlTimer=null; } return {dl:Object.assign({},s.dl,{pct:100,status:'done'})}; }
      return {dl:Object.assign({},s.dl,{pct:p})};
    });
  },50);
}
closeDl(){ if(this._dlTimer){ clearInterval(this._dlTimer); this._dlTimer=null; } this.setState({dl:null}); }
fmtSize(total,pct){
  const m=(total||'').match(/([\d.,]+)\s*(.+)/);
  if(!m) return '';
  const num=parseFloat(m[1].replace(',','.'));
  const cur=num*pct/100;
  const dec=cur<10?2:(cur<100?1:0);
  return cur.toFixed(dec).replace('.',',')+' '+m[2];
}

